using System;using System.Collections.Generic;using System.Text;public class Solution{public string FractionToDecimal(int n,int d){if(n==0)return"0";long a=n,b=d;var r=new StringBuilder();if((a<0)^(b<0))r.Append('-');a=Math.Abs(a);b=Math.Abs(b);r.Append(a/b);long rem=a%b;if(rem==0)return r.ToString();r.Append('.');var m=new Dictionary<long,int>();while(rem!=0){if(m.ContainsKey(rem)){r.Insert(m[rem],"(");r.Append(')');break;}m[rem]=r.Length;rem*=10;r.Append(rem/b);rem%=b;}return r.ToString();}}
